import{_ as a}from"./chunks/chat-diagnostics.HMJaz4jC.js";import{_ as s,o as t,c as n,ag as o}from"./chunks/framework.DqVSm8kp.js";const g=JSON.parse('{"title":"Diagnostics de Chat","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/chat-diagnostics.md","filePath":"fr/guide/chat-diagnostics.md"}'),i={name:"fr/guide/chat-diagnostics.md"};function r(l,e,d,c,u,m){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="diagnostics-de-chat" tabindex="-1">Diagnostics de Chat <a class="header-anchor" href="#diagnostics-de-chat" aria-label="Permalink to &quot;Diagnostics de Chat&quot;">​</a></h1><p>La page Diagnostics de Chat est le coeur de LLMxRay. Elle combine une interface de chat complete avec une analyse approfondie en temps reel de chaque token produit par le modele.</p><p><strong>Element de la barre laterale :</strong> Diagnostics de Chat (premier element) <strong>Route :</strong> <code>/</code></p><p><img src="'+a+'" alt="Interface Diagnostics de Chat"></p><h2 id="vue-d-ensemble-de-l-interface" tabindex="-1">Vue d&#39;ensemble de l&#39;interface <a class="header-anchor" href="#vue-d-ensemble-de-l-interface" aria-label="Permalink to &quot;Vue d&#39;ensemble de l&#39;interface&quot;">​</a></h2><p>La page est divisee en deux zones :</p><ul><li><strong>Panneau gauche</strong> -- Liste des sessions affichant toutes les conversations passees avec horodatage, noms de modeles et nombre de tokens.</li><li><strong>Panneau droit</strong> -- Zone de chat active avec saisie de message, sortie en streaming et onglets de detail de session.</li></ul><h2 id="demarrer-une-conversation" tabindex="-1">Demarrer une conversation <a class="header-anchor" href="#demarrer-une-conversation" aria-label="Permalink to &quot;Demarrer une conversation&quot;">​</a></h2><ol><li>Selectionnez un modele dans le <strong>menu deroulant des modeles</strong> en haut. Les modeles d&#39;embedding sont automatiquement filtres -- seuls les modeles capables de chat apparaissent.</li><li>Saisissez votre message dans la zone de texte.</li><li>Appuyez sur <strong>Entree</strong> ou cliquez sur Envoyer.</li></ol><p>Les tokens arrivent un par un avec une <strong>coloration par confiance</strong> : chaque token est teinte en fonction de la vitesse a laquelle le modele l&#39;a produit. Tokens rapides = confiance elevee (plus vert). Tokens lents = confiance faible (plus orange/rouge).</p><div class="info custom-block"><p class="custom-block-title">La confiance est une approximation</p><p>Comme le endpoint <code>/api/chat</code> d&#39;Ollama n&#39;expose pas les logprobs des tokens, LLMxRay approxime la confiance a partir de la latence inter-tokens. Cela est clairement indique dans l&#39;interface. Pour de vrais logprobs, utilisez la fonctionnalite <a href="./benchmark.html">Benchmark</a>.</p></div><h2 id="fonctionnalites" tabindex="-1">Fonctionnalites <a class="header-anchor" href="#fonctionnalites" aria-label="Permalink to &quot;Fonctionnalites&quot;">​</a></h2><h3 id="rendu-markdown" tabindex="-1">Rendu Markdown <a class="header-anchor" href="#rendu-markdown" aria-label="Permalink to &quot;Rendu Markdown&quot;">​</a></h3><p>Les reponses du modele sont rendues en Markdown enrichi avec coloration syntaxique des blocs de code.</p><h3 id="fichiers-joints" tabindex="-1">Fichiers joints <a class="header-anchor" href="#fichiers-joints" aria-label="Permalink to &quot;Fichiers joints&quot;">​</a></h3><p>Cliquez sur le bouton de piece jointe pour telecharger des fichiers. Pour les <strong>modeles de vision</strong> (comme LLaVA), vous pouvez coller ou telecharger des images directement -- le modele les analysera.</p><h3 id="commandes-slash" tabindex="-1">Commandes slash <a class="header-anchor" href="#commandes-slash" aria-label="Permalink to &quot;Commandes slash&quot;">​</a></h3><p>Tapez <code>/</code> dans la zone de saisie pour voir les commandes slash disponibles pour des actions rapides.</p><h3 id="conversation-multi-tours" tabindex="-1">Conversation multi-tours <a class="header-anchor" href="#conversation-multi-tours" aria-label="Permalink to &quot;Conversation multi-tours&quot;">​</a></h3><p>Chaque conversation conserve l&#39;historique complet des messages. Le modele voit tous les messages precedents comme contexte.</p><h2 id="analyse-approfondie-des-sessions" tabindex="-1">Analyse approfondie des sessions <a class="header-anchor" href="#analyse-approfondie-des-sessions" aria-label="Permalink to &quot;Analyse approfondie des sessions&quot;">​</a></h2><p>Cliquez sur une session dans le panneau gauche pour explorer six onglets d&#39;analyse :</p><h3 id="onglet-stream" tabindex="-1">Onglet Stream <a class="header-anchor" href="#onglet-stream" aria-label="Permalink to &quot;Onglet Stream&quot;">​</a></h3><p>Chaque token avec ses donnees de timing affiche dans une liste deroulante. Au-dessus de la liste de tokens, un <strong>tableau de bord de metriques</strong> affiche :</p><ul><li><strong>TTFT</strong> (Time to First Token) -- Temps mis par le modele pour commencer a repondre</li><li><strong>Tokens/sec</strong> -- Vitesse de generation</li><li><strong>Total tokens</strong> -- Nombre de tokens (prompt + completion)</li><li><strong>Graphique de latence</strong> -- Chronologie visuelle des delais inter-tokens</li></ul><h3 id="onglet-raisonnement" tabindex="-1">Onglet Raisonnement <a class="header-anchor" href="#onglet-raisonnement" aria-label="Permalink to &quot;Onglet Raisonnement&quot;">​</a></h3><p>Si vous utilisez un modele de raisonnement comme <strong>DeepSeek-R1</strong>, les blocs <code>&lt;think&gt;</code> sont automatiquement analyses et affiches etape par etape. Chaque etape de raisonnement est categorisee comme pensee, observation, action, conclusion ou reflexion.</p><h3 id="onglet-introspection" tabindex="-1">Onglet Introspection <a class="header-anchor" href="#onglet-introspection" aria-label="Permalink to &quot;Onglet Introspection&quot;">​</a></h3><p>Visualisations des activations de couches, cartes de chaleur d&#39;attention et architecture du modele.</p><div class="warning custom-block"><p class="custom-block-title">Donnees illustratives</p><p>Ces visualisations utilisent des donnees synthetiques pour montrer a quoi ressemblerait une veritable introspection. Elles sont clairement etiquetees &quot;Illustratif&quot; dans l&#39;interface. L&#39;introspection reelle necessite un acces aux mecanismes internes du modele qu&#39;Ollama n&#39;expose pas.</p></div><h3 id="onglet-outils" tabindex="-1">Onglet Outils <a class="header-anchor" href="#onglet-outils" aria-label="Permalink to &quot;Onglet Outils&quot;">​</a></h3><p>Une chronologie de tous les appels d&#39;outils effectues par le modele pendant la conversation, montrant :</p><ul><li>Nom de l&#39;outil et parametres</li><li>Resultat de l&#39;execution</li><li>Duree</li></ul><h3 id="onglet-agent" tabindex="-1">Onglet Agent <a class="header-anchor" href="#onglet-agent" aria-label="Permalink to &quot;Onglet Agent&quot;">​</a></h3><p>Un graphe de flux d&#39;etats montrant comment un prompt de type agent a progresse a travers les etapes de planification, d&#39;appels d&#39;outils et de synthese.</p><h3 id="onglet-prompt" tabindex="-1">Onglet Prompt <a class="header-anchor" href="#onglet-prompt" aria-label="Permalink to &quot;Onglet Prompt&quot;">​</a></h3><p>Une analyse anatomique de votre prompt montrant :</p><ul><li>Les sections identifiees (systeme, utilisateur, contexte, outils, exemples)</li><li>Le nombre de tokens par section</li><li>L&#39;analyse de la structure globale</li></ul><h2 id="astuces" tabindex="-1">Astuces <a class="header-anchor" href="#astuces" aria-label="Permalink to &quot;Astuces&quot;">​</a></h2><ul><li><strong>Persistance des sessions</strong> -- Toutes les conversations sont stockees dans IndexedDB et survivent aux actualisations du navigateur.</li><li><strong>Changement de modele</strong> -- Vous pouvez changer de modele en cours de session. Le nouveau modele verra l&#39;historique complet de la conversation.</li><li><strong>Performance</strong> -- Le store de tokens utilise <code>shallowRef</code> pour garantir les performances avec des milliers de tokens.</li></ul>',40)])])}const f=s(i,[["render",r]]);export{g as __pageData,f as default};
